rewrites:
buySignal := buySignal or chTriB or chSniB
sellSignal := sellSignal or chTriS or chSniS

// ══ ① إصلاح البوابة ═══════════════════════════════════════════════════════
// مفتاح Trade Side ومرشّح الجلسة/التذبذب يُطبَّقان عند السطرين ٢٤٣١ و٢٤٧٧، ثم
// تتجاوزهما ٢١ إسناد OR لاحقاً فتدخل صفقات ممنوعة. إعادة تطبيقهما هنا تصلحهما.
buySignal  := buySignal  and allowLong  and not sfBlock
sellSignal := sellSignal and allowShort and not sfBlock

// ══ ② مرشّح الدخول المتأخر ════════════════════════════════════════════════
// قياس على ١٩٢٠٨١ شمعة: حين يدخل المؤشر بعد أن تحرّك السعر في اتجاه الإشارة
// أكثر من ٣ ATR تنزل نسبة الربح إلى ٤٨.٤٤٪، وحين يدخل عكس الحركة ترتفع إلى ٦٣.٠٥٪.
// حجب الإشارات المتأخرة: ٦٠.٥١٪ ← ٦٢.٢٠٪ وصافي +٧٠٩١ ← +٩٥٨٦، والعدد يبقى
// ٤٨.٣ صفقة/يوم لأن حجب الإشارة يترك المركز حراً لإشارة أفضل بعدها.
lateUse    = input.bool(true,  "② مرشّح الدخول المتأخر", group=G_MAIN_NEW)
lateBars   = input.int(5,      "② شموع قياس الاندفاع المسبق", minval=1, maxval=30, group=G_MAIN_NEW)
lateMaxAtr = input.float(0.2,  "② أقصى حركة مسبقة في اتجاه الإشارة (ATR)", step=0.1, group=G_MAIN_NEW)
lateAtr    = ta.atr(14)
lateMove   = (close - close[lateBars]) / math.max(lateAtr, syminfo.mintick)
buySignal  := buySignal  and (not lateUse or  lateMove < lateMaxAtr)
sellSignal := sellSignal and (not lateUse or -lateMove < lateMaxAtr)
